// Construye el payload del componente de dashboard.
// El componente lee el MER directamente desde PostgreSQL y actualiza el
// libro Excel en OneDrive mediante Microsoft Graph (OAuth 2.0).
const config = $('Configuración').first().json;

return [
  {
    json: {
      workflowId: 'dashboard-ejecutivo',
      periodoInicio: config.periodo_inicio,
      periodoFin: config.periodo_fin,
      fuenteDatos: 'postgres',
      actualizarExcel: Boolean(config.excel_drive_item_id),
      excelDriveItemId: config.excel_drive_item_id || undefined,
      excelWorksheetName: config.excel_worksheet_name,
    },
  },
];

// Redacta la notificación del dashboard a partir de la respuesta del
// componente y del resumen del MER consultado en PostgreSQL.
const config = $('Configuración').first().json;
const resumen = $('Consultar Resumen MER').first().json;
const respuesta = $('Invocar Dashboard').first().json;

const d = respuesta.data ?? respuesta;
const financiero = d.resumenFinanciero ?? {};
const trazabilidad = d.resumenAutomatizaciones ?? {};
const kpis = d.kpis ?? {};
const comercial = Array.isArray(d.seguimientoComercial) ? d.seguimientoComercial : [];
const monitoreo = Array.isArray(d.monitoreoIntegraciones) ? d.monitoreoIntegraciones : [];
const control = d.controlActualizacion ?? {};

const numero = (valor, decimales = 0) =>
  new Intl.NumberFormat('es-CO', {
    minimumFractionDigits: decimales,
    maximumFractionDigits: decimales,
  }).format(Number(valor ?? 0));

const fecha = (iso) =>
  iso
    ? new Intl.DateTimeFormat('es-CO', { dateStyle: 'short', timeStyle: 'short' }).format(
        new Date(iso),
      )
    : '—';

const lineas = [
  'DASHBOARD EJECUTIVO — ASESOR FINTECH',
  `Periodo: ${config.periodo_etiqueta}`,
  `Actualizado: ${d.fechaActualizacion ?? config.inicio_ejecucion}`,
  `Origen de los datos: ${d.datosSinteticos ? 'SINTÉTICOS (demostración)' : 'REALES (PostgreSQL · MER)'}`,
  '',
  'INDICADORES CLAVE DE GESTIÓN (KPIs)',
  `- Leads registradas: ${numero(kpis.leadsRegistradas)}`,
  `- Citas agendadas: ${numero(kpis.citasAgendadas)}`,
  `- Inversiones registradas: ${numero(kpis.inversionesRegistradas)}`,
  `- Conversión: ${numero(kpis.conversionPorcentaje, 2)} %`,
  '',
  'BLOQUE A — SEGUIMIENTO COMERCIAL',
  ...(comercial.length > 0
    ? comercial.map(
        (f) =>
          `- ${f.estado} (${f.etapaComercial}): ${numero(f.cantidad)} · ${numero(f.participacionPorcentaje, 2)} %`,
      )
    : ['- Sin leads en el periodo.']),
  '',
  'BLOQUE B — CAMPAÑAS MAILCHIMP',
  ...(Array.isArray(d.campañasMailchimp) && d.campañasMailchimp.length > 0
    ? d.campañasMailchimp.map(
        (c) => `- ${c.nombre} (${c.estado}): suscriptores ${numero(c.suscriptores)}`,
      )
    : ['- Sin campañas registradas en el periodo.']),
  '',
  'BLOQUE C — CITAS DEL PERIODO',
  `- Citas confirmadas: ${numero(Array.isArray(d.citasSemana) ? d.citasSemana.length : 0)}`,
  '',
  'BLOQUE D — RESUMEN FINANCIERO',
  `- Monto acumulado (inversiones activas): ${numero(financiero.montoAcumulado ?? financiero.saldoTotalInversionesActivas)} COP`,
  `- Total de operaciones: ${numero(financiero.totalOperaciones)}`,
  `- Operaciones pendientes: ${numero(financiero.operacionesPendientes)}`,
  `- Operaciones completadas: ${numero(financiero.operacionesCompletadas)}`,
  `- Operaciones del mes actual: ${numero(financiero.numeroOperacionesMesActual)}`,
  `- Variación % frente al mes anterior: ${numero(financiero.variacionPorcentualMesAnterior, 2)} %`,
  '',
  'MONITOREO DE INTEGRACIONES',
  ...(monitoreo.length > 0
    ? monitoreo.map((m) => `- ${m.plataforma}: ${fecha(m.ultimaSincronizacion)} · ${m.estado}`)
    : ['- Sin datos de sincronización en el periodo.']),
  '',
  'CONTROL DE ACTUALIZACIÓN',
  `- Última actualización: ${fecha(control.ultimaActualizacion)}`,
  `- Estado general: ${control.estadoGeneral ?? '—'}`,
  '',
  'TRAZABILIDAD DE AUTOMATIZACIONES (automation_log)',
  `- Ejecuciones del periodo: ${numero(trazabilidad.totalEjecuciones)}`,
  `- Con error: ${numero(trazabilidad.ejecucionesConError)} · Con advertencia: ${numero(trazabilidad.ejecucionesConAdvertencia)}`,
  '',
  'RESUMEN DEL MER EN POSTGRESQL',
  `- Leads captados en el periodo: ${numero(resumen.leads_periodo)}`,
  `- Citas en el periodo: ${numero(resumen.citas_periodo)}`,
  `- Inversiones activas: ${numero(resumen.inversiones_activas)}`,
  `- Campañas registradas: ${numero(resumen.campanas)}`,
];

if (d.excelActualizado) {
  lineas.push(
    '',
    `Libro Excel actualizado en OneDrive: ${d.excelActualizado.filasEscritas} fila(s) escritas en la hoja «${config.excel_worksheet_name}».`,
  );
} else {
  lineas.push('', 'El libro Excel no se actualizó: no se configuró DASHBOARD_EXCEL_DRIVE_ITEM_ID.');
}

if (Array.isArray(d.advertencias) && d.advertencias.length > 0) {
  lineas.push('', 'NOTAS', ...d.advertencias.map((a) => `- ${a}`));
}

return [
  {
    json: {
      destinatario: config.destinatario,
      remitente: config.remitente,
      asunto: `Dashboard Ejecutivo — ${config.periodo_etiqueta}`,
      cuerpo: lineas.join('\n'),
      total_registros:
        Number(resumen.leads_periodo ?? 0) +
        Number(resumen.citas_periodo ?? 0) +
        Number(resumen.inversiones_activas ?? 0),
      latencia_ms: Math.max(0, Date.now() - Date.parse(config.inicio_ejecucion)),
    },
  },
];
